def predict(shape, barrier, seeds):
    h,w=shape
    out=set()
    for r,c in seeds:
        if r == barrier-2:
            # V apex one row below seed, sides expand upward by one column per row.
            for k in range(h):
                rr=r+1-k
                if not (0 <= rr < h): continue
                for cc in {c-k,c+k}:
                    if 0 <= cc < w: out.add((rr,cc))
        else:
            if r+1 < h: out.add((r+1,c))
    return out
for i,(shape,b,seeds,expected) in enumerate(demos,1):
